{"policy":"permit (
    principal is Person,
    action == Action::"examinePatentApplication",
    resource is PatentApplication
)
when {
    principal.roles.contains(Role::"examiner") &&
    context.mfaUsed &&
    principal != resource.inventor
};

forbid (
    principal is Person,
    action == Action::"examinePatentApplication",
    resource is PatentApplication
)
when {
    principal.roles.contains(Role::"examiner") &&
    !context.mfaUsed
};

forbid (
    principal is Person,
    action == Action::"examinePatentApplication",
    resource is PatentApplication
)
when {
    principal.roles.contains(Role::"examiner") &&
    principal == resource.inventor
};"}
